/*Table structure for table `sku_image` */

CREATE TABLE `sku_image` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `sku_id` bigint DEFAULT NULL COMMENT '商品id',
  `img_name` varchar(200) DEFAULT NULL COMMENT '图片名称（冗余）',
  `img_url` varchar(300) DEFAULT NULL COMMENT '图片路径(冗余)',
  `spu_img_id` bigint DEFAULT NULL COMMENT '商品图片id',
  `is_default` varchar(4000) DEFAULT NULL COMMENT '是否默认',
  `create_time` datetime DEFAULT NULL,
  `operate_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=197 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='库存单元图片表';

