  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `sku_id` bigint DEFAULT NULL COMMENT '库存单元id',
  `spu_id` int DEFAULT NULL COMMENT 'spu_id(冗余)',
  `sale_attr_value_id` bigint DEFAULT NULL COMMENT '销售属性值id',
